CREATE OR REPLACE FUNCTION public.fn_get_milestones_for_child(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, child_id uuid, classroom_id uuid, teacher_id uuid, title character varying, description text, milestone_date timestamp with time zone, development_area_id uuid, evidence_summary text, journey_entry_id uuid, parent_visible boolean, status character varying, created_at timestamp with time zone, created_by uuid, updated_at timestamp with time zone, updated_by uuid)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT cm.id, cm.tenant_id, cm.child_id, cm.classroom_id, cm.teacher_id,            cm.title, cm.description, cm.milestone_date, cm.development_area_id,            cm.evidence_summary, cm.journey_entry_id, cm.parent_visible, cm.status,            cm.created_at, cm.created_by, cm.updated_at, cm.updated_by     FROM child_milestones cm     WHERE cm.tenant_id = p_tenant_id AND cm.child_id = p_child_id     ORDER BY cm.milestone_date DESC; END; $function$ ;
